CompanyManagement = {
  init: async function (app, container) {
    app = app || session.app;
    container = container || $(".component[name=CompanyManagement]");

    api.addToMetaCache([
      {
        "Name": "B2B",
        "Types": [
          [meta[B2B/Company]],
        ]
      }
    ]);

    await CompanyManagement.setup(app, container);
  },

  setup: async function (app, container) {

    var ds = await model.getDatasource({
      endpoint: "B2B/Company",
      odataAppend: "?$expand=Address,References"
    });

    var grid = new GridWidget(container, ds);

    grid.groupable = false;
    grid.toolbar = "<button type='button' class='btn btn-primary btn-sm' name='create'><span class='k-icon k-i-plus'></span>[resource_displayname[newcompany]]</button>";
    grid.pageable = {
      refresh: true,
      buttonCount: 5
    };
    grid.filterable = true;

    grid.columns = [
      { field: "Name", title: "[resource_shortdisplayname[Name]]", width: 250 },
      { field: "ContactEmailAddress", title: "[resource_displayname[ContactEmailAddress]]", width: 250 },
      { field: "ContactPhoneNumber", title: "[resource_displayname[ContactPhoneNumber]]", width: 250 },
      { field: "WebsiteUrl", title: "[resource_displayname[WebsiteUrl]]", width: 250 },
      { field: "DateTradingEnabled", title: "[resource_displayname[DateTradingEnabled]]", format: "{0:" + type.dateFormat + "}" }
    ];

    grid.commands.push({ name: "save", text: "[resource_displayname[save]]", icon: "k-i-save" });
    grid.commands.push({ name: "delete", text: "[resource_displayname[delete]]", icon: "k-i-trash" });

    grid.dataBound = () => {
      $("[name=save]", grid.gridElement).on("click", (e) => CompanyManagement.save(e, grid));
      $("[name=delete]", grid.gridElement).on("click", (e) => CompanyManagement.destroy(e, grid));
    };

    grid.detailTemplate = kendo.template($("script[name=companyDetails]", container.parent()).html());

    grid.detailExpand = async function (e) {

      var detailRow = $(e.detailRow);
      var item = e.sender.dataItem($(e.masterRow));

      if (!detailRow.data("initialized")) {
        var html = $("script[name=companyDetails]").html();
        detailRow.find(".k-detail-cell").html(html);
        detailRow.data("initialized", true);
      }

      if (detailRow.find("[name=CompanyReferenceManagement]").length == 0) {
        var c = await loadComponent($("[name=references]", detailRow), "CompanyReferenceManagement");
        await c.init(app, $(".component[name=CompanyReferenceManagement]", detailRow), item);
      }

      detailRow.find("[name=PoBox]").val(item.Address?.PoBox || "");
      detailRow.find("[name=Line1]").val(item.Address?.Line1 || "");
      detailRow.find("[name=Line2]").val(item.Address?.Line2 || "");
      detailRow.find("[name=ZipOrPostalCode]").val(item.Address?.ZipOrPostalCode || "");
      detailRow.find("[name=TownOrCity]").val(item.Address?.TownOrCity || "");
      detailRow.find("[name=StateOrProvince]").val(item.Address?.StateOrProvince || "");
      detailRow.find("[name=IsVerified]").prop("checked", !!item.IsVerified);

      const countriesResponse = await api.get("B2B/Country");
      const countries = countriesResponse.value || [];

      const $countrySelect = detailRow.find("select[name=CountryId]");
      $countrySelect.empty();
      $countrySelect.append(`<option value="">[resource_displayname[SelectCountry]]</option>`);

      countries.forEach(c => {
        $countrySelect.append(`<option value="${c.Id}">${c.Name}</option>`);
      });

      if (item.Address?.CountryId) {
        $countrySelect.val(item.Address.CountryId);
      }

      detailRow.find("button[name=saveAddress]")
        .off("click")
        .on("click", async () => {

          var updatedAddress = {
            Id: item.Address.Id,
            PoBox: detailRow.find("[name=PoBox]").val(),
            Line1: detailRow.find("[name=Line1]").val(),
            Line2: detailRow.find("[name=Line2]").val(),
            ZipOrPostalCode: detailRow.find("[name=ZipOrPostalCode]").val(),
            TownOrCity: detailRow.find("[name=TownOrCity]").val(),
            StateOrProvince: detailRow.find("[name=StateOrProvince]").val(),
            CountryId: detailRow.find("[name=CountryId]").val(),
            IsActive: item.Address.IsActive,
            LastUpdated: new Date().toISOString()
          };

          var updatedCompany = {
            Id: item.Id,
            Name: item.Name,
            ContactEmailAddress: item.ContactEmailAddress,
            ContactPhoneNumber: item.ContactPhoneNumber,
            WebsiteUrl: item.WebsiteUrl,
            IsActive: item.IsActive,
            IsVerified: detailRow.find("[name=IsVerified]").prop("checked"), // now correctly mapped
            Address: updatedAddress,
            References: item.References || []
          };

          try {
            await api.put(`B2B/Company(${item.Id})`, updatedCompany);
            notification.success("[resource_displayname[saved]]");
          } catch (err) {
            error(err);
          }
        });

      e.sender.resize();
    };

    await grid.init();

    $("button[name=create]", grid.gridElement)
      .on("click", function (e) {
        CompanyManagement.newCompany(e, grid);
      });
  },

  setupAddressEditing: async function (company, container) {

    if (!company.Address) {
      var address = await model.item.createInstance("B2B/Address");
      company.Address = address.prepForPush();
      delete company.Address.Id;
    }

    var addressModel = new kendo.data.ObservableObject(company.Address);

    var config = {
      endpoint: "B2B/Country",
      serverOptions: {
        filtering: false,
        sorting: false,
        paging: false,
        grouping: false
      }
    };

    var countryData = await model.getDatasource(config);

    $("input[name=CountryId]", container).kendoDropDownList({
      dataSource: countryData,
      dataTextField: "Name",
      dataValueField: "Id"
    });

    kendo.bind(container, addressModel);
    container.data("model", addressModel);

    addressModel.bind("change", function () {
      for (var p in company.Address) {
        company.Address[p] = [p];
      }
    });
  },

  newCompany: async function (e, grid) {

    var companyInfoEditor = {
      Name: "",
      ContactEmailAddress: "",
      ContactPhoneNumber: "",
      WebsiteUrl: "",
      SystemId: "",
      Value: "",
      Line1: "",
      Line2: "",
      ZipOrPostalCode: "",
      TownOrCity: "",
      StateOrProvince: "",
      CountryId: ""
    };

    var args = {
      fields: [
        { field: "Name", title: "[resource_displayname[name]]", description: "[resource_description[name]]" },
        { field: "ContactEmailAddress", title: "[resource_displayname[contactemailaddress]]", description: "[resource_description[contactemailaddress]]" },
        { field: "ContactPhoneNumber", title: "[resource_displayname[contactphonenumber]]", description: "[resource_description[contactphonenumber]]" },
        { field: "WebsiteUrl", title: "[resource_displayname[websiteurl]]", description: "[resource_description[websiteurl]]" },
        { field: "SystemId", title: "[resource_displayname[systemid]]", description: "[resource_description[systemid]]" },
        { field: "Value", title: "[resource_displayname[value]]", description: "[resource_description[value]]" },
        { field: "Line1", title: "[resource_displayname[line1]]", description: "[resource_description[line1]]" },
        { field: "Line2", title: "[resource_displayname[line2]]", description: "[resource_description[line2]]" },
        { field: "ZipOrPostalCode", title: "[resource_displayname[ziporportalcode]]", description: "[resource_description[ziporpostalcode]]" },
        { field: "TownOrCity", title: "[resource_displayname[townorcity]]", description: "[resource_description[townorcity]]" },
        { field: "StateOrProvince", title: "[resource_displayname[stateorprovince]]", description: "[resource_description[stateorprovince]]" },
        { field: "CountryId", title: "[resource_displayname[countryid]]", description: "[resource_description[countryid]]" }
      ],
      title: "[resource_displayname[newcompany]]",
      resourceKey: "B2B",
      data: companyInfoEditor
    };

    var addCompanyDialog = new EditorDialog(args);

    addCompanyDialog.events.confirm = async function () {

      companyInfoEditor = addCompanyDialog.data.toJSON();

      var newCompany = {
        Name: companyInfoEditor.Name,
        ContactEmailAddress: companyInfoEditor.ContactEmailAddress,
        ContactPhoneNumber: companyInfoEditor.ContactPhoneNumber,
        WebsiteUrl: companyInfoEditor.WebsiteUrl,
        References: [
          { SystemId: companyInfoEditor.SystemId, Value: companyInfoEditor.Value }
        ],
        Address: {
          Line1: companyInfoEditor.Line1,
          Line2: companyInfoEditor.Line2,
          ZipOrPostalCode: companyInfoEditor.ZipOrPostalCode,
          TownOrCity: companyInfoEditor.TownOrCity,
          StateOrProvince: companyInfoEditor.StateOrProvince,
          CountryId: companyInfoEditor.CountryId
        }
      };

      await api.add("B2B/Company", newCompany)
        .then(() => {
          notification.success('[resource_description[CompanyCreated]]');
          grid.refresh();
        })
        .catch((err) => error(err));
    };

    addCompanyDialog.init();
  },

  save: function (e, grid) {
    e.preventDefault();
    var company = grid.dataItem($(e.currentTarget).closest("tr"));
    company.save(e, function () {
      notification.success("[resource_description[CompanySaved]]");
    });
  },

  destroy: function (e, grid) {
    e.preventDefault();

    var d = new ConfirmDialog({
      title: "[resource_displayname[areyousure]]",
      confirm: "[resource_displayname[confirm]]",
      close: "[resource_displayname[close]]",
      question: "[resource_displayname[areyousure]]"
    });

    d.events.confirm = function () {
      var company = grid.dataItem($(e.currentTarget).closest("tr"));

      company.destroy(e).then(() => {
        notification.success("[resource_description[CompanyDeleted]]");
        grid.refresh();
        d.events.close();
      });
    };

    d.init();
  }
};
